);

INSERT INTO emergency_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (10, true, '10|||קבלת סיוע נפשי מיידי', '10|||מענה דחוף של קב״ן, 24/7. בטלפון.', '{"org":"מערך בריאות הנפש, צה״ל","svc":"מענה דחוף של קב״ן, 24/7. בטלפון.","target":"חיילים בסדיר ובמילואים","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"*6690, שלוחה 4, במוקד מקול הלב. למקרה שאינו דחוף פונים לקב״ן דרך המפקד או מרפאת היחידה. חיילים משוחררים פונים ליחידה לתגובות קרב או לנפש אחת, בכרטיסים נפרדים.","meeting":"","web":"https://www.idf.il/%D7%90%D7%AA%D7%A8%D7%99-%D7%99%D7%97%D7%99%D7%93%D7%95%D7%AA/%D7%90%D7%92%D7%A3-%D7%94%D7%98%D7%9B%D7%A0%D7%95%D7%9C%D7%95%D7%92%D7%99%D7%94-%D7%95%D7%94%D7%9C%D7%95%D7%92%D7%99%D7%A1%D7%98%D7%99%D7%A7%D7%94/%D7%9B%D7%9C-%D7%94%D7%9B%D7%AA%D7%91%D7%95%D7%AA/2025/%D7%A1%D7%99%D7%95%D7%A2-%D7%A0%D7%A4%D7%A9%D7%99-%D7%91%D7%A6%D7%94-%D7%9C-%D7%90%D7%99%D7%9A-%D7%A4%D7%95%D7%A0%D7%99%D7%9D-%D7%9C%D7%A7%D7%91-%D7%9F-%D7%95%D7%9C%D7%90%D7%9F-%D7%9E%D7%AA%D7%A7%D7%A9%D7%A8%D7%99%D7%9D/","add":"","addLabel":"","phone":"*6690","phoneLabel":"שלוחה 4","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Mental Health Array, IDF","svc":"Urgent response from an IDF mental-health officer, 24/7. By phone.","target":"Regular and reserve soldiers","region":"Nationwide","cost":"At no cost","notes":"Extension 4 at the Makol Halev call center. A case that is not urgent goes to the unit mental-health officer through the commander or the unit clinic. Discharged soldiers go to the Combat Response Unit or to Nefesh Ahat, on separate cards.","phone":"*6690","phoneLabel":"Extension 4","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '26.11.2026: נבדק מול עמוד צה״ל מ-14.10.2026, סיוע נפשי בצה״ל. העמוד כותב *6690 שלוחה 4. עמוד מ-2023 כותב שלוחה 3. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (11, true, '11|||קו המעניק תמיכה נפשית ראשונית', '11|||תמיכה נפשית ראשונית, 24/7. בטלפון.', '{"org":"נפש אחת (אגף השיקום, משרד הבטחון)","svc":"תמיכה נפשית ראשונית, 24/7. בטלפון.","target":"נכי צה״ל וכוחות הביטחון, חיילים משוחררים עם פוסט טראומה, מי שהגיש בקשה להכרה, ובני משפחה","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר לפנות בעילום שם. המענה של נט״ל. צוות מתן בכרטיס נפרד.","meeting":"","web":"https://shikum.mod.gov.il/ContactUs/helpline","add":"","addLabel":"","phone":"*8944","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Nefesh Ahat (Rehabilitation Division, Ministry of Defense)","svc":"Initial mental-health support, 24/7. By phone.","target":"IDF and security-forces disabled people, discharged soldiers with post-traumatic stress, a person who filed a recognition request, and family members","region":"Nationwide","cost":"At no cost","notes":"It is possible to call without giving a name. The response is from Natal. The Matan team is on a separate card.","phone":"*8944","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '26.11.2026: נבדק מול https://shikum.mod.gov.il/ContactUs/helpline. *8150 הוא מרכזייה, לא הקו הזה. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (20, true, '20|||קו סיוע והכוונה', '20|||עזרה ראשונה נפשית אנונימית, 24/7. בטלפון או בכתב.', '{"org":"ער״ן","svc":"עזרה ראשונה נפשית אנונימית, 24/7. בטלפון או בכתב.","target":"כל אדם. חיילים בסדיר, בקבע ובמילואים, ובני משפחותיהם, בקו נפרד.","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם צ׳אט באתר. יש קווים לקהילות, בכמה שפות.","meeting":"","web":"https://www.eran.org.il/","add":"","addLabel":"","phone":"1201","phoneLabel":"כללי","phoneShowNumber":false,"phone2":"*2201","phoneLabel2":"חיילים","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"whatsapp":"972528451201","whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"ERAN","svc":"Anonymous mental-health first aid, 24/7. By phone or in writing.","target":"Any person. Regular, career, and reserve soldiers, and their family members, on a separate line.","region":"Nationwide","cost":"At no cost","notes":"Also a chat on the site. There are lines for communities, in several languages.","phone":"1201","phoneLabel":"General","phone2":"*2201","phoneLabel2":"Soldiers","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","whatsapp":"972528451201","whatsappLabel":"WhatsApp"}'::jsonb, '26.11.2026: נבדק מול https://www.eran.org.il/services/ ועמוד החיילים. הוואטסאפ 052-8451201. 052-8451202 ומספר המטה ירדו. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (30, false, '30|||רשימת מרכזי חוסן ברחבי הארץ', '30|||טיפול ממוקד טראומה למי שנחשף ישירות לאירוע ביטחוני. בטלפון, בזום או במרכז.', '{"org":"מרכזי חוסן","svc":"טיפול ממוקד טראומה למי שנחשף ישירות לאירוע ביטחוני. בטלפון, בזום או במרכז.","target":"ילדים, נוער ומבוגרים","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"פונים לפי אזור המגורים. מי שאין באזור שלו מרכז פונה למרכז הארצי. חשיפה דרך התקשורת אינה נכללת.","meeting":"both","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/public-care/community-treatment/resilience-center/","add":"https://www.gov.il/he/Departments/DynamicCollectors/resilience-centers-list","addLabel":"רשימת המרכזים","phone":"*5486","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Resilience centers","svc":"Trauma-focused treatment for a person who was directly exposed to a security event. By phone, on Zoom, or at the center.","meeting":"both","target":"Children, youth, and adults","region":"Nationwide","cost":"At no cost","notes":"People apply according to the area where they live. A person whose area has no center applies to the national center. Exposure through the media is not included.","phone":"*5486","phoneLabel":"Call center","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","addLabel":"List of the centers"}'::jsonb, '26.11.2026: נבדק מול דף מרכזי החוסן במשרד הבריאות. השעות א-ה לא עולות. 24/7 מתואר למצב מיוחד בעורף, לא כשירות קבוע. על הספה באותה שורה לא נגע. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (39, true, '39|||בית בטוח לטיפול מיידי - חלופת אשפוז', '39|||חלופת אשפוז מיידית לפוסט טראומה, כולל איזון תרופתי. בשהייה בבית החולים.', '{"org":"אגף השיקום, משרד הבטחון","svc":"חלופת אשפוז מיידית לפוסט טראומה, כולל איזון תרופתי. בשהייה בבית החולים.","target":"נכי צה״ל שהוכרו עם פוסט טראומה, או מי שנמצא בתהליך הכרה על פגיעה נפשית, במשבר שדורש מיון או השגחה","region":"באר שבע, ירושלים, טירת הכרמל, תל השומר, באר יעקב","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"עד 10 ימים, עד 6 אנשים. בתוך בית החולים, בנפרד מהמחלקה. אפשר להגיע למיון בלי התחייבות. לא מתאים לאובדנות פעילה, לפסיכוזה פעילה או לשימוש בחומרים. בירושלים, שלוחה 2815.","meeting":"in_person","web":"https://shikum.mod.gov.il/medical/mental-therapy/safe_housing","add":"","addLabel":"","phone":"052-4614896","phoneLabel":"באר שבע","phoneShowNumber":false,"phone2":"02-6551303","phoneLabel2":"ירושלים","phoneShowNumber2":false,"phone3":"050-3682799","phoneLabel3":"ירושלים נייד","phoneShowNumber3":false,"phone4":"050-3627283","phoneLabel4":"טירת הכרמל","phoneShowNumber4":false,"phone5":"052-6669512","phoneLabel5":"תל השומר","phoneShowNumber5":false,"phone6":"08-9258271","phoneLabel6":"באר יעקב","phoneShowNumber6":false}'::jsonb, '{"org":"Rehabilitation Division, Ministry of Defense","svc":"An immediate alternative to hospitalization for post-traumatic stress, including medication balancing. While staying at the hospital.","meeting":"in_person","target":"IDF disabled people recognized with post-traumatic stress, or a person in a recognition process for a mental injury, in a crisis that needs an emergency evaluation or supervision","region":"Beer Sheva, Jerusalem, Tirat Carmel, Tel Hashomer, Beer Yaakov","cost":"At no cost","notes":"Up to 10 days, up to 6 people. Inside the hospital, separate from the ward. It is possible to arrive at the emergency room without a commitment form. Not suitable for active suicidality, active psychosis, or substance use. In Jerusalem, extension 2815.","phone":"052-4614896","phoneLabel":"Beer Sheva","phone2":"02-6551303","phoneLabel2":"Jerusalem","phone3":"050-3682799","phoneLabel3":"Jerusalem mobile","phone4":"050-3627283","phoneLabel4":"Tirat Carmel","phone5":"052-6669512","phoneLabel5":"Tel Hashomer","phone6":"08-9258271","phoneLabel6":"Beer Yaakov"}'::jsonb, '26.11.2026: נבדק מול https://shikum.mod.gov.il/medical/mental-therapy/safe_housing. טירת הכרמל 050-3627283. באר יעקב 08-9258271 חדש. *8944 ירד מהכרטיס. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (77, true, '77|||Israel''s Emergency Mental Health Resources During War - Comprehensive list of mental health resources', '77|||רשימת מענים נפשיים באנגלית, לתקופת מלחמה.', '{"org":"Avnei Chein","svc":"רשימת מענים נפשיים באנגלית, לתקופת מלחמה.","target":"","region":"","cost":"","specialty":"","approaches":"","languages":"אנגלית","diseases":"","notes":"הרשימה לא נבדקה על ידי הארגון. כרטיס השירותים של הארגון נפרד.","meeting":"","web":"https://www.avneichein.org/emergency-mental-health-resources/","add":"","addLabel":"","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Avnei Chein","svc":"A list of mental-health responses in English, for wartime.","languages":"English","notes":"The list was not checked by the organization. The services card of the organization is separate.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '26.11.2026: נבדק מול https://www.avneichein.org/emergency-mental-health-resources/. העמוד כותב שהרשימה לא נבדקה. המספרים בעמוד צמודים למפגש זום מתאריך נקוב, ולא עלו לכרטיס. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (101, true, '101|||אפליקציה חינמית המספקת עזרה ראשונה נפשית ותמיכה מיידית בזמן התקף חרדה, ומלווה את המשתמש עד חזרה הדרגתית לשגרה.', '101|||עזרה ראשונה נפשית בהתקף חרדה. באפליקציה.', '{"org":"אפליקציית Rescue","svc":"עזרה ראשונה נפשית בהתקף חרדה. באפליקציה.","target":"","region":"","cost":"ללא עלות","specialty":"","approaches":"","languages":"עברית, אנגלית","diseases":"חרדה","notes":"נבנתה עם פסיכולוגים ופסיכיאטרים.","meeting":"","web":"https://rescueanxietyapp.org/","add":"","addLabel":"","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Rescue app","svc":"Mental-health first aid during a panic attack. In the app.","cost":"At no cost","languages":"Hebrew, English","diseases":"Anxiety","notes":"Built with psychologists and psychiatrists.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '26.11.2026: נבדק מול https://rescueanxietyapp.org/. המשפט שהאפליקציה אינה תחליף לטיפול ירד. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (200, true, '200|||קווי המענה הארציים של ארגון הגג למרכזי הסיוע', '200|||סיוע ותמיכה אחרי פגיעה מינית. בטלפון או בצ׳אט.', '{"org":"איגוד מרכזי הסיוע לנפגעות ולנפגעי תקיפה מינית","svc":"סיוע ותמיכה אחרי פגיעה מינית. בטלפון או בצ׳אט.","target":"נפגעות ונפגעי תקיפה מינית ובני משפחותיהם","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"תהל, לחברה הדתית והחרדית, בכרטיס נפרד.","meeting":"","web":"https://1202.org.il/","add":"https://1202kolmila.org.il/","addLabel":"צ׳אט","phone":"1202","phoneLabel":"נשים","phoneShowNumber":false,"phone2":"1203","phoneLabel2":"גברים","phoneShowNumber2":false,"phone3":"04-6566813","phoneLabel3":"ערבית","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"whatsapp":"972528361202","whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"Association of Rape Crisis Centers","svc":"Assistance and support after sexual assault. By phone or in a chat.","target":"Women and men who experienced sexual assault, and their family members","region":"Nationwide","notes":"Tahel, for religious and Haredi communities, is on a separate card.","phone":"1202","phoneLabel":"Women","phone2":"1203","phoneLabel2":"Men","phone3":"04-6566813","phoneLabel3":"Arabic","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","whatsapp":"972528361202","whatsappLabel":"WhatsApp","addLabel":"Chat"}'::jsonb, '26.11.2026: נבדק מול https://1202.org.il/. *2511 ו-02-5328000 נשארים בכרטיס תהל. נוסף 04-6566813. העמוד שנפתח אינו כותב 24/7. הניסוח אושר עם אצוות העזרה הדחופה.'),
  (236, true, '236|||מידע, סיוע והכוונה — 24/7', '236|||מידע וסיוע ראשוני, 24/7. בטלפון.', '{"org":"מוקד 118, משרד הרווחה והביטחון החברתי","svc":"מידע וסיוע ראשוני, 24/7. בטלפון.","target":"","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"לא ביום כיפור. אפשר גם לשלוח הודעת טקסט ל-050-2270118.","meeting":"","web":"https://www.gov.il/he/departments/general/molsa-118","add":"","addLabel":"","phone":"118","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Hotline 118, Ministry of Welfare and Social Security","svc":"Information and initial assistance, 24/7. By phone.","region":"Nationwide","cost":"At no cost","notes":"Not on Yom Kippur. It is also possible to send a text message to 050-2270118.","phone":"118","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '26.11.2026: עמוד המשרד בעברית לא נפתח. הפרטים תואמים לעמוד המשרד בערבית ולכל זכות, שמציין את https://www.gov.il/he/departments/general/molsa-118. 077-9208560 ירד. 050-2270118 הוא מסרון, לא כפתור. הניסוח אושר עם אצוות העזרה הדחופה.'),
